import pandas as pd
p='/output/raw/eea_metadata.csv'
df=pd.read_csv(p,sep='\\t',low_memory=False)
x=df[df.Countrycode.eq('IT')]
print(x.shape, x.columns.tolist())
print(x[['SamplingPoint','Longitude','Latitude','AirPollutantCode','ObservationDateBegin']].head().to_string(index=False))
print(x.Latitude.min(),x.Latitude.max(),x.Longitude.min(),x.Longitude.max())
PY
